  function notebook() { saveUnsavedNote(); $('#notebook-content').innerHTML = notebookEntries() + '<div class="button-row"><button class="primary" id="export-journal">Export journal</button><button class="secondary" id="import-journal">Import journal</button></div><p class="fine">The exported JSON includes your photos. Keep it private if it contains personal images.</p>'; $('#export-journal').onclick = exportJournal; $('#import-journal').onclick = importJournal; $('#notebook-dialog').showModal(); }
